#include <iostream>
#include <vector>
#include <set>
#include <climits>
#include <algorithm>
#include <iomanip>
#include <cassert>
#include <limits>

using namespace std;

using i64 = long long;

static constexpr int MAX_N = 5007;
static constexpr i64 LARGE_INF = 1000000000LL;
static constexpr i64 MOD_VAL = 1000000007LL;

struct FlowEdge {
    int from_node;
    int to_node;
    i64 max_capacity;
    i64 unit_cost;
    i64 current_flow;

    FlowEdge(int f, int t, i64 cap, i64 cst)
        : from_node(f), to_node(t), max_capacity(cap), unit_cost(cst), current_flow(0) {}
};

vector<FlowEdge> all_edges;
i64 shortest_path_dist[MAX_N];
i64 potential[MAX_N];
vector<int> adjacency_list[MAX_N];
int predecessor_edge[MAX_N];

void insert_bidirectional_edge(int u, int v, i64 cap, i64 cost) {
    adjacency_list[u].push_back(all_edges.size());
    all_edges.emplace_back(u, v, cap, cost);
    adjacency_list[v].push_back(all_edges.size());
    all_edges.emplace_back(v, u, 0, -cost);
}

void initialize_potentials(int source, int num_nodes) {
    fill(potential, potential + MAX_N, LARGE_INF);
    potential[source] = 0;
    for (int iter = 0; iter < num_nodes; ++iter) {
        for (size_t idx = 0; idx < all_edges.size(); ++idx) {
            auto& e = all_edges[idx];
            if (e.max_capacity == e.current_flow) continue;
            if (potential[e.from_node] == LARGE_INF) continue;
            potential[e.to_node] = min(potential[e.to_node], potential[e.from_node] + e.unit_cost);
        }
    }
}

void compute_shortest_paths(int source) {
    fill(shortest_path_dist, shortest_path_dist + MAX_N, LARGE_INF);
    shortest_path_dist[source] = 0;
    set<pair<i64, int>> ordered_set;
    ordered_set.insert({0, source});
    while (!ordered_set.empty()) {
        auto [cur_dist, node] = *ordered_set.begin();
        ordered_set.erase(ordered_set.begin());
        for (int edge_index : adjacency_list[node]) {
            auto& e = all_edges[edge_index];
            if (e.max_capacity == e.current_flow) continue;
            int next_node = e.to_node;
            i64 adjusted_weight = e.unit_cost + potential[node] - potential[next_node];
            if (shortest_path_dist[node] + adjusted_weight < shortest_path_dist[next_node]) {
                ordered_set.erase({shortest_path_dist[next_node], next_node});
                shortest_path_dist[next_node] = shortest_path_dist[node] + adjusted_weight;
                predecessor_edge[next_node] = edge_index;
                ordered_set.insert({shortest_path_dist[next_node], next_node});
            }
        }
    }
}

pair<i64, i64> min_cost_max_flow_computation(int source, int sink) {
    initialize_potentials(source, 50);
    compute_shortest_paths(source);
    i64 total_flow = 0, total_expense = 0;
    while (shortest_path_dist[sink] != LARGE_INF) {
        i64 augment = numeric_limits<i64>::max();
        i64 sum_cost = 0;
        int cursor = sink;
        while (cursor != source) {
            int idx = predecessor_edge[cursor];
            augment = min(augment, all_edges[idx].max_capacity - all_edges[idx].current_flow);
            sum_cost += all_edges[idx].unit_cost;
            cursor = all_edges[idx].from_node;
        }
        total_flow += augment;
        total_expense += augment * sum_cost;
        cursor = sink;
        while (cursor != source) {
            int idx = predecessor_edge[cursor];
            all_edges[idx].current_flow += augment;
            all_edges[idx ^ 1].current_flow -= augment;
            cursor = all_edges[idx].from_node;
        }
        compute_shortest_paths(source);
        for (int i = 0; i < MAX_N; ++i) potential[i] = shortest_path_dist[i];
    }
    return {total_expense, total_flow};
}

void run_test_case() {
    int n, m, k, c_param, d_param;
    cin >> n >> m >> k >> c_param >> d_param;
    vector<int> vertex_demands(n, 0);
    for (int i = 0; i < k; ++i) {
        int vertex;
        cin >> vertex;
        vertex_demands[--vertex]++;
    }
    for (int i = 0; i < n; ++i) {
        insert_bidirectional_edge(5000, i, vertex_demands[i], 0);
    }
    for (int time_step = 0; time_step < m; ++time_step) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        for (int layer = 0; layer < 99; ++layer) {
            i64 edge_cost = d_param;
            for (int iteration = 0; iteration < 50; ++iteration) {
                insert_bidirectional_edge(u + layer * 50, v + (layer + 1) * 50, 1, edge_cost);
                insert_bidirectional_edge(v + layer * 50, u + (layer + 1) * 50, 1, edge_cost);
                edge_cost += 2 * d_param;
            }
        }
    }
    for (int layer = 0; layer <= 99; ++layer) {
        insert_bidirectional_edge(0 + layer * 50, 5001, numeric_limits<i64>::max(), c_param * layer);
    }
    for (int i = 0; i < n; ++i) {
        for (int layer = 0; layer < 99; ++layer) {
            insert_bidirectional_edge(i + layer * 50, i + (layer + 1) * 50, numeric_limits<i64>::max(), 0);
        }
    }
    auto result = min_cost_max_flow_computation(5000, 5001);
    assert(result.second == k);
    cout << result.first;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(20);
    run_test_case();
    return 0;
}
